import{_ as e,o as r,c as s,a2 as a}from"./chunks/framework.ChIlRNAd.js";const c=JSON.parse('{"title":"Activity","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/activity.md","filePath":"en/guide/activity.md"}'),o={name:"en/guide/activity.md"};function n(i,t,d,l,h,u){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h1><p>The <strong>Activity</strong> page (<code>/activity</code>) lists &quot;everything you and your rules started, live&quot;: bulk actions, NAS backups, rules, scans, imports, purges… It replaces the former &quot;Job Tracking&quot; page.</p><p>On desktop, the sidebar shows &quot;N running&quot; next to <strong>Activity</strong>; on mobile, the page is under <strong>More › Tools</strong>.</p><hr><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><ul><li><strong>Gmail account</strong>: one account or <strong>All accounts</strong>. Instance-wide tasks (with no account) are marked <strong>Instance</strong>.</li><li><strong>Status</strong>, as chips with a counter: <strong>All</strong>, <strong>Waiting</strong>, <strong>Running</strong>, <strong>Failed</strong>, <strong>Completed</strong>.</li></ul><p>Filters are kept in the page address.</p><hr><h2 id="task-list" tabindex="-1">Task list <a class="header-anchor" href="#task-list" aria-label="Permalink to &quot;Task list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Content</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>Pending, Scheduled, Running, Completed, Failed, Cancelled</td></tr><tr><td><strong>Task</strong></td><td>task type, account, and origin: &quot;Rule&quot;, &quot;Cleanup › sender&quot;, &quot;Mails › query&quot; or &quot;Retry&quot;</td></tr><tr><td><strong>Progress / result</strong></td><td>live progress bar, &quot;Done · N emails processed&quot;, error message, &quot;Stopped&quot;…</td></tr><tr><td><strong>Duration</strong></td><td>run time</td></tr></tbody></table><p>&quot;Waiting&quot; groups the tasks queued and those waiting for their undo window to end (10 s after a deletion, for instance).</p><p>The footer reads &quot;N of M · history kept for 30 days&quot;; <strong>Show more</strong> loads the rest.</p><hr><h2 id="actions-by-status" tabindex="-1">Actions by status <a class="header-anchor" href="#actions-by-status" aria-label="Permalink to &quot;Actions by status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Action</th></tr></thead><tbody><tr><td>Waiting</td><td><strong>Cancel</strong>: the task will not run</td></tr><tr><td>Running</td><td><strong>Stop</strong>, in the progress bar</td></tr><tr><td>Failed</td><td><strong>Retry</strong> and <strong>Details</strong> (start date and error message)</td></tr><tr><td>Completed</td><td><strong>View</strong>: opens the related page (Mail, Rules, Cleanup, Archives…), otherwise <strong>Details</strong></td></tr></tbody></table><p>An IMAP import task cannot be retried from here, since the password is not stored: &quot;This task needs credentials that are not stored: start it again from its page.&quot;</p><hr><h2 id="elsewhere-in-the-app" tabindex="-1">Elsewhere in the app <a class="header-anchor" href="#elsewhere-in-the-app" aria-label="Permalink to &quot;Elsewhere in the app&quot;">​</a></h2><p>A task&#39;s progress also shows where it was started (sender row in Cleanup, Archives header, Mail list), and the <a href="./overview.html">Overview</a> lists running jobs. When a task ends, a <a href="./notifications.html">notification</a> may be sent depending on your preferences.</p>',19)])])}const p=e(o,[["render",n]]);export{c as __pageData,p as default};
